    if (s.ws_floats < need) {
        s.workspace = torch::empty({need}, torch::dtype(torch::kFloat32).device(params.device()));
        s.ws_floats = need;
    }
    // PERSISTENT grad buffer (one per process, zeroed in-place each step) — avoids a
